/* Settings (NuHome live design): Company, Navigation, Humans, Rulebook, Usage — plus Personal, Templates, Tax, Shipping, Invoices (reachable from Company). */
(function () {
  const { esc, icon: I, fmt } = DM;
  const st = document.createElement('style'); st.dataset.for = 'settings';
  st.textContent = `
  .st-card{margin-bottom:14px}.st-card .body{padding:14px 16px}
  .st-card .hd{display:flex;align-items:flex-start;gap:10px;padding:14px 16px 0}.st-card .hd h3{font-size:14px;font-weight:600}.st-card .hd .s{font-size:12px;color:var(--muted-foreground);margin-top:1px}
  .st-row{display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border)}.st-row:last-child{border-bottom:0}
  .st-eyebrow{font-size:10.5px;text-transform:uppercase;letter-spacing:.07em;color:#8a8a8a;font-weight:500;margin:18px 0 8px}
  .co-id{display:flex;align-items:center;gap:14px;margin-bottom:18px}.co-id h1{font-size:20px;font-weight:600;display:flex;gap:8px;align-items:center}
  .logo-tile{border-radius:14px;display:grid;place-items:center;flex:none;overflow:hidden}.logo-tile img{width:100%;height:100%;object-fit:cover}
  .logo-box{margin:12px 16px 16px;border:1px solid var(--border);border-radius:12px;padding:12px 14px;display:flex;align-items:center;gap:14px;background:#fafafa}
  .rec{display:grid;grid-template-columns:1fr 1fr;gap:16px 24px;padding:14px 16px 18px}.rec dt{font-size:11px;color:var(--muted-foreground)}.rec dd{font-size:13px;font-weight:500;margin-top:2px}.rec dd.none{color:#a3a3a3;font-weight:400}
  .ent{display:grid;grid-template-columns:1fr 1fr;gap:10px 24px;padding:14px 16px 16px;border-top:1px solid var(--border);margin-top:12px}.ent div{display:flex;gap:8px;align-items:center;font-size:13px}.ent svg.i{width:13px;height:13px}
  .lnk{display:flex;align-items:center;gap:12px;padding:11px 16px;border-bottom:1px solid var(--border)}.lnk:last-child{border:0}.lnk:hover{background:var(--hover-cream)}
  .modrow{display:grid;grid-template-columns:22px minmax(0,1fr) 200px 56px auto;gap:12px;align-items:center;padding:9px 16px;border-bottom:1px solid var(--border)}.modrow:last-child{border:0}
  .modrow .mcode{font:11.5px ui-monospace,Menlo,monospace;color:#737373}
  .chips{display:flex;flex-wrap:wrap;gap:6px}.chip{display:inline-flex;align-items:center;gap:6px;border:1px solid #f1c6c6;background:#fff7f7;color:#262626;border-radius:999px;font-size:12px;padding:3px 6px 3px 10px}.chip button{display:grid;place-items:center;color:#a3a3a3}.chip button:hover{color:#e03a3a}.chip svg.i{width:11px;height:11px}
  .addphrase{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:#525252;padding:3px 8px;border-radius:999px}.addphrase:hover{background:var(--muted)}
  .vtext p{font-size:13px;line-height:1.5;margin-bottom:8px}.vtext p:last-child{margin:0}
  .vlab{font-size:11px;font-weight:600;color:#525252;margin:12px 0 4px}
  .hu-tabs{display:flex;gap:4px;border-bottom:1px solid var(--border);margin:14px 0 0}.hu-tabs button{padding:8px 10px;font-size:12.5px;color:var(--muted-foreground);border-bottom:2px solid transparent;margin-bottom:-1px;display:flex;gap:6px;align-items:center}.hu-tabs button.on{color:var(--foreground);border-color:var(--foreground);font-weight:500}
  .av-dark{width:22px;height:22px;border-radius:50%;background:#0a0a0a;color:#fff;font-size:9px;font-weight:600;display:inline-grid;place-items:center;flex:none}
  .member-chip{border:1px solid var(--border);border-radius:6px;font-size:11px;padding:1px 8px;background:#fff;font-weight:500}
  .cyc{padding:14px 16px}.cyc .big{font-size:13px}.cyc .track{height:8px;border-radius:4px;background:#eee;margin:10px 0 6px;overflow:hidden}.cyc .track i{display:block;height:100%;background:#0a0a0a;border-radius:4px}
  .donuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:12px 0 8px}.dcard{padding:12px 14px;display:flex;gap:12px;align-items:center}
  .legend{display:flex;gap:16px;font-size:11.5px;color:#737373;margin:6px 2px 14px;align-items:center}.legend i{display:inline-block;vertical-align:middle;margin-right:5px}
  .ubar{position:relative;height:8px;border-radius:4px;background:#eee;margin:8px 0 6px}.ubar .u{position:absolute;left:0;top:0;bottom:0;background:#13a269;border-radius:4px}.ubar .p{position:absolute;top:0;bottom:0;background:repeating-linear-gradient(90deg,#13a269 0 2px,transparent 2px 5px);opacity:.55}.ubar .t{position:absolute;top:-3px;bottom:-3px;width:2px;background:#404040;border-radius:1px}
  .urow{padding:14px 16px;border-bottom:1px solid var(--border)}.urow:last-child{border:0}
  .inv-prev{background:#fff;border:1px solid var(--border);border-radius:8px;padding:24px;font-size:12.5px}
  .sw{width:26px;height:26px;border-radius:7px;cursor:pointer;border:2px solid transparent}.sw.on{border-color:#171717;outline:2px solid #fff;outline-offset:-4px}
  @media(max-width:900px){.rec,.ent,.donuts{grid-template-columns:1fr}.modrow{grid-template-columns:22px minmax(0,1fr) auto}.modrow .mcode{display:none}}`;
  document.head.appendChild(st);

  /* ───────── helpers ───────── */
  const uc = () => DM.uc;
  const KEEP = ['voice', 'modules', 'roles', 'invites', 'company', 'settings', 'users', 'rulebook', 'templates', 'moduleLabels'];
  const keep = (DM.ui.stKeep = DM.ui.stKeep || {});
  const persist = () => { const k = (keep[uc()] = keep[uc()] || {}); KEEP.forEach((key) => { if (DM.S[key] !== undefined) k[key] = DM.clone(DM.S[key]); }); k.navHidden = (DM.S.navHidden || []).slice(); };
  const rs = DM.resetState;
  DM.resetState = function () { rs.apply(this, arguments); const k = keep[DM.uc]; if (k) Object.keys(k).forEach((key) => { DM.S[key] = DM.clone(k[key]); }); };
  const done = (msg, icon) => { persist(); if (msg) DM.toast(msg, icon); DM.render(); };

  const page = (title, sub, body, acts = '', back) => `<div class="page">${back ? `<a class="btn ghost sm" href="#${back[0]}" style="margin:-6px 0 6px -8px">${I('arrowL')} ${esc(back[1])}</a>` : ''}${DM.header(title, sub, acts)}${body}</div>`;
  const reg = (key, title, render, opts = {}) => { const f = (ctx) => render(ctx); DM.page('/settings/' + key, { title, crumb: title, render: f }); if (opts.sub) DM.page('/settings/' + key + '/*', { title, crumb: title, render: f }); };
  const getp = (p) => p.split('.').reduce((o, k) => (o == null ? o : o[k]), DM.S);
  const setp = (p, v) => { const ks = p.split('.'); const last = ks.pop(); let o = DM.S; ks.forEach((k) => { o = o[k] = o[k] || {}; }); o[last] = v; };
  const inp = (label, p, o = {}) => `<div class="field" ${o.span ? 'style="grid-column:1/-1"' : ''}><label>${esc(label)}</label>${o.options ? `<select class="select" data-change="st-set" data-p="${p}">${o.options.map((x) => `<option ${String(x) === String(getp(p)) ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select>` : o.area ? `<textarea class="textarea" data-input="st-set" data-p="${p}" rows="${o.rows || 3}">${esc(getp(p) || '')}</textarea>` : `<input class="input" type="${o.type || 'text'}" data-input="st-set" data-p="${p}" value="${esc(getp(p) ?? '')}">`}${o.hint ? `<div class="xs muted">${esc(o.hint)}</div>` : ''}</div>`;
  DM.input('st-set', (v, el) => { const cur = getp(el.dataset.p); setp(el.dataset.p, typeof cur === 'number' ? +v : v); persist(); });
  DM.act('st-flip', (el) => { setp(el.dataset.arg, !getp(el.dataset.arg)); done(); });
  DM.act('st-save', (el) => DM.toast(el.dataset.arg || 'Saved'));
  const card = (title, sub, body, foot, right = '') => `<div class="card st-card"><div class="hd"><div class="grow"><h3>${title}</h3>${sub ? `<div class="s">${sub}</div>` : ''}</div>${right}</div><div class="body">${body}</div>${foot ? `<div style="padding:10px 16px;border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end;background:#fafafa;border-radius:0 0 14px 14px">${foot}</div>` : ''}</div>`;
  const S = () => DM.S.settings || (DM.S.settings = {
    personal: { name: 'Demo Admin', email: 'admin@demo.anuma.run', phone: '+91 98200 11223', language: 'English', timezone: 'Asia/Kolkata (IST)', notifyApp: true, notifyEmail: true, notifyWhatsapp: true, digest: true },
    taxes: { defaultRate: 18, inclusive: false, hsnRequired: true, rates: [{ id: 'g0', name: 'GST 0%', rate: 0, on: true }, { id: 'g5', name: 'GST 5%', rate: 5, on: true }, { id: 'g12', name: 'GST 12%', rate: 12, on: true }, { id: 'g18', name: 'GST 18%', rate: 18, on: true }, { id: 'g28', name: 'GST 28%', rate: 28, on: false }] },
    shipping: { freeAbove: 25000, flat: 150, pickup: 'Main warehouse', carriers: [{ id: 'sr', name: 'Shiprocket', on: true, mode: 'Surface' }, { id: 'dl', name: 'Delhivery', on: true, mode: 'Surface' }, { id: 'bd', name: 'Blue Dart', on: false, mode: 'Air' }], zones: [{ id: 'z1', name: 'Within state', days: '1–2', rate: 90 }, { id: 'z2', name: 'Metro cities', days: '2–4', rate: 150 }, { id: 'z3', name: 'Rest of India', days: '4–7', rate: 220 }] },
    invoices: { prefix: 'INV/26-27/', next: 1042, terms: 'Payment due within the agreed credit terms. Interest @ 18% p.a. on overdue amounts. Subject to local jurisdiction.', bank: 'HDFC Bank · A/c 5020 0012 3456 78 · IFSC HDFC0001234', signature: true, qr: true, showHsn: true },
  });
  const pencil = (act, arg = '') => `<button class="btn ghost icon sm" data-act="${act}" data-arg="${esc(arg)}" title="Edit">${I('edit')}</button>`;

  /* ───────── Company ───────── */
  const logo = (c, px) => c.logoImg ? `<span class="logo-tile" style="width:${px}px;height:${px}px"><img src="${c.logoImg}" alt=""></span>` : `<span class="logo-tile" style="width:${px}px;height:${px}px;background:${esc(c.logoColor || '#0a0a0a')}"><svg viewBox="0 0 32 32" width="${Math.round(px * .62)}" height="${Math.round(px * .62)}"><circle cx="10.5" cy="16" r="2.3" fill="#fff"/><rect x="15" y="13.8" width="8.5" height="4.4" rx="2.2" fill="#fff"/></svg></span>`;
  const rec = (k, v) => `<div><dt>${esc(k)}</dt><dd class="${v ? '' : 'none'}">${v ? esc(v) : 'Not set'}</dd></div>`;
  reg('organisation', 'Company', () => {
    const c = DM.S.company || (DM.S.company = { name: 'Demo Merchant User' }); const p = DM.S.plan || { name: 'Growth plan', title: 'Growth', entitlements: [] };
    const body = `<div class="co-id">${logo(c, 52)}<div><h1>${esc(c.name)} <span class="badge outline">${esc(p.name)}</span></h1><div class="sm muted">${esc(c.handle || '@demo-merchant')} · ${esc(c.timezone || 'Asia/Kolkata')}</div></div></div>
      ${card('Logo', 'Shown on quotes, order confirmations and this workspace.', `<div class="logo-box" style="margin:0">${logo(c, 40)}<div class="grow"><div class="b sm">Current logo</div><div class="xs muted">PNG, JPG, SVG or WebP, up to 2 MB.</div></div>${c.logoImg ? `<button class="btn ghost sm" data-act="st-logo-rm">Remove</button>` : ''}<button class="btn sm" data-act="st-logo-up">${I('upload')} Replace</button></div>`, '', `<span class="icotile">${I('image')}</span>`)}
      <div class="card st-card"><div class="hd"><div class="grow"><h3>Company record</h3><div class="s">Who the business is, as it appears on invoices and to dealers.</div></div><button class="btn outline sm" data-act="st-co-edit">${I('edit')} Edit</button><button class="btn outline icon sm" data-act="st-co-doc" title="Download record">${I('file')}</button></div>
        <dl class="rec">${rec('Legal name', c.legal || c.name)}${rec('Billing email', c.email)}${rec('Phone', c.phone)}${rec('Customer email', c.supportEmail)}${rec('Domain', c.domain || c.website)}${rec('Handle', c.handle)}${rec('GSTIN', c.gstin)}${rec('Timezone', c.timezone)}${rec('Address', [c.address, c.city].filter(Boolean).join(', '))}${rec('Currency', c.currency)}</dl></div>
      <div class="card st-card"><div class="hd"><div class="grow"><h3 style="font-size:17px">${esc(p.title || 'Growth')}</h3><div class="s">renewal</div></div><span class="stat-badge green"><i></i>${esc(p.status || 'Active')}</span></div><div class="ent">${(p.entitlements || []).map((e) => `<div>${I('check')}<span>${esc(e)}</span></div>`).join('')}</div></div>
      <div class="st-eyebrow">More settings</div><div class="card st-card">${[['personal', 'Personal', 'Your profile and notification preferences', 'user'], ['templates', 'Templates', 'Message templates for WhatsApp, email and quotes', 'palette'], ['taxes', 'Tax', 'GST rates applied to products, quotes and invoices', 'percent'], ['shipping', 'Shipping', 'Carriers, zones and free-shipping rules', 'truck'], ['invoices', 'Invoices', 'Numbering, terms and layout of tax invoices', 'receipt']].map(([k, l, d, ic]) => `<a class="lnk" href="#/settings/${k}"><span class="icotile">${I(ic)}</span><div class="grow"><div class="b sm">${l}</div><div class="xs muted">${d}</div></div>${I('chevR')}</a>`).join('')}</div>`;
    return `<div class="page">${body}</div>`;
  });
  DM.act('st-logo-up', () => { const f = document.createElement('input'); f.type = 'file'; f.accept = 'image/png,image/jpeg,image/svg+xml,image/webp'; f.onchange = () => { const file = f.files[0]; if (!file) return; if (file.size > 2 * 1024 * 1024) { DM.toast('Logo must be under 2 MB', 'alert'); return; } const r = new FileReader(); r.onload = () => { DM.S.company.logoImg = r.result; done('Logo replaced'); }; r.readAsDataURL(file); }; f.click(); });
  DM.act('st-logo-rm', () => { delete DM.S.company.logoImg; done('Logo removed'); });
  DM.act('st-co-doc', () => { const c = DM.S.company; const t = Object.entries(c).filter(([k]) => k !== 'logoImg').map(([k, v]) => k + ': ' + v).join('\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([t], { type: 'text/plain' })); a.download = 'company-record.txt'; document.body.appendChild(a); a.click(); a.remove(); DM.toast('Company record downloaded', 'download'); });
  DM.act('st-co-edit', () => { const c = DM.S.company; DM.modal({ lg: true, title: 'Edit company record', body: `<div class="grid g2">${DM.field('Legal name', 'legal', { value: c.legal || '' })}${DM.field('Billing email', 'email', { value: c.email || '' })}${DM.field('Phone', 'phone', { value: c.phone || '' })}${DM.field('Customer email', 'supportEmail', { value: c.supportEmail || '' })}${DM.field('Domain', 'domain', { value: c.domain || '' })}${DM.field('Handle', 'handle', { value: c.handle || '' })}${DM.field('GSTIN', 'gstin', { value: c.gstin || '' })}${DM.field('Timezone', 'timezone', { options: ['Asia/Kolkata', 'Asia/Dubai', 'Europe/London'], value: c.timezone || 'Asia/Kolkata' })}${DM.field('Currency', 'currency', { options: ['INR', 'USD', 'AED'], value: c.currency || 'INR' })}${DM.field('City', 'city', { value: c.city || '' })}</div><div style="margin-top:12px">${DM.field('Address', 'address', { value: c.address || '', area: true, rows: 2 })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (m) => { const f = DM.formData(m); if (f.email && !/@/.test(f.email)) { DM.toast('Enter a valid billing email', 'alert'); return false; } Object.assign(c, f); done('Company record saved'); } }] }); });

  /* ───────── Personal ───────── */
  reg('personal', 'Personal', () => {
    const p = S().personal;
    return page('Personal', 'Your own profile and notification preferences.', card('Profile', null, `<div class="row gap12" style="margin-bottom:14px">${DM.avatar(p.name, 'lg')}<button class="btn outline sm" data-act="toast" data-arg="Photo updated">Change photo</button></div><div class="grid g2">${inp('Full name', 'settings.personal.name')}${inp('Email', 'settings.personal.email')}${inp('Phone', 'settings.personal.phone')}${inp('Language', 'settings.personal.language', { options: ['English', 'हिन्दी', 'ગુજરાતી', 'मराठी'] })}${inp('Time zone', 'settings.personal.timezone', { options: ['Asia/Kolkata (IST)', 'Asia/Dubai (GST)', 'Europe/London (GMT)'] })}</div>`, DM.btn('Save profile', 'st-save', { cls: 'sm', arg: 'Profile saved' }))
      + `<div class="card st-card"><div class="hd"><h3>Notifications</h3></div>${[['notifyApp', 'In-app', 'Bell and inbox badges'], ['notifyEmail', 'Email', 'Approvals and daily digest'], ['notifyWhatsapp', 'WhatsApp', 'When a case needs you'], ['digest', 'Morning digest', 'A summary at 9:00 AM']].map(([k, l, d]) => `<div class="st-row"><div class="grow"><div class="sm b">${l}</div><div class="xs muted">${d}</div></div>${DM.switch(p[k], 'st-flip', 'settings.personal.' + k)}</div>`).join('')}</div>`
      + card('Security', null, `<div class="row"><div class="grow"><div class="sm b">Password</div><div class="xs muted">Last changed 3 months ago</div></div><button class="btn outline sm" data-act="st-pw">Change password</button></div>`), '', ['/settings/organisation', 'Company']);
  });
  DM.act('st-pw', () => DM.modal({ title: 'Change password', body: `<div class="col gap12">${DM.field('Current password', 'a', { type: 'password' })}${DM.field('New password', 'b', { type: 'password' })}${DM.field('Confirm new password', 'c', { type: 'password' })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Update password', run: (m) => { const f = DM.formData(m); if (!f.b || f.b.length < 8) { DM.toast('Use at least 8 characters', 'alert'); return false; } if (f.b !== f.c) { DM.toast('Passwords do not match', 'alert'); return false; } DM.toast('Password updated', 'check'); } }] }));

  /* ───────── Navigation ───────── */
  const NU = () => (DM.ui.stNavUi = DM.ui.stNavUi || { q: '' });
  const mods = () => DM.S.modules || (DM.S.modules = []);
  reg('navigation', 'Navigation', () => {
    const q = NU().q.toLowerCase(); const hidden = DM.S.navHidden || []; const labels = DM.S.moduleLabels || {};
    const rows = mods().filter((m) => !q || (m.label + ' ' + m.code + ' ' + (labels[m.code] || '')).toLowerCase().includes(q));
    const list = rows.map((m) => { const lab = labels[m.code] || m.label; const ren = m.renamed || labels[m.code]; return `<div class="modrow"><span style="color:#737373">${I(m.icon || 'grid')}</span><div class="sm" style="min-width:0"><span class="b" style="font-weight:500">${esc(lab)}</span>${ren ? ' <span class="xs muted" style="margin-left:6px">renamed</span>' : ''}</div><span class="mcode trunc">${esc(m.code)}</span><span>${m.rail ? DM.switch(!hidden.includes(m.rail), 'st-modnav', m.rail) : ''}</span><span class="row gap4">${pencil('st-modren', m.code)}<button class="btn ghost icon sm" data-act="st-modfld" data-arg="${esc(m.code)}" title="Custom fields${(m.fields || []).length ? ' · ' + m.fields.length : ''}">${I('wand')}</button></span></div>`; }).join('');
    return page('Navigation', 'Rename the modules that appear in your workspace, and manage the custom fields captured on their entities.',
      `<div class="card st-card"><div class="hd"><div class="grow"><h3>Modules</h3><div class="s">Rename a module's label, or manage the custom fields captured on it. Use the switch to show it in the sidebar.</div></div><span class="icotile">${I('list')}</span></div><div class="row" style="padding:12px 16px">${DM.searchBox('st-modq', 'Search modules…', NU().q)}<span class="xs muted right">${mods().length} modules</span></div>${list || '<div class="empty">No modules match.</div>'}</div>`,
      (hidden.length ? `<button class="btn outline sm" data-act="st-navreset">${I('rotate')} Restore sidebar</button>` : '') + `<span class="badge outline">${I('building')} Demo Merchant User</span>`);
  });
  DM.input('st-modq', (v) => { NU().q = v; DM.render(); });
  DM.act('st-modnav', (el) => { const k = el.dataset.arg; const h = (DM.S.navHidden = DM.S.navHidden || []); const i = h.indexOf(k); if (i >= 0) h.splice(i, 1); else h.push(k); done(i >= 0 ? 'Shown in sidebar' : 'Hidden from sidebar'); });
  DM.act('st-navreset', () => { DM.S.navHidden = []; done('Sidebar restored'); });
  DM.act('st-modren', (el) => { const m = DM.by(mods(), el.dataset.arg, 'code'); const labels = (DM.S.moduleLabels = DM.S.moduleLabels || {}); DM.modal({ title: 'Rename module', body: `<div class="col gap12"><div class="sm muted">Code <span class="monotag">${esc(m.code)}</span>. The new label shows wherever this module is named.</div>${DM.field('Label', 'label', { value: labels[m.code] || m.label })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (d) => { const v = DM.formData(d).label.trim(); if (!v) { DM.toast('Label cannot be empty', 'alert'); return false; } labels[m.code] = v; done('Renamed to ' + v); } }] }); });
  DM.act('st-modfld', (el) => { const m = DM.by(mods(), el.dataset.arg, 'code'); const draw = () => `<div class="col" style="gap:8px">${(m.fields || []).length ? m.fields.map((f, i) => `<div class="row" style="border:1px solid var(--border);border-radius:10px;padding:8px 10px"><span class="grow sm b">${esc(f.name)}</span><span class="badge">${esc(f.type)}</span><button class="btn ghost icon sm" data-fld-del="${i}">${I('trash')}</button></div>`).join('') : '<div class="muted sm">No custom fields yet.</div>'}</div>`;
    DM.modal({ title: 'Custom fields · ' + esc(m.label), body: `<div id="fld-list">${draw()}</div><div class="sep"></div><div class="row"><input class="input grow" id="fld-name" placeholder="Field name"><select class="select" id="fld-type" style="width:120px">${['Text', 'Number', 'Select', 'Date', 'Link'].map((t) => `<option>${t}</option>`).join('')}</select><button class="btn sm" id="fld-add">${I('plus')} Add</button></div>`, actions: [{ label: 'Done' }], onMount: (d) => { const redraw = () => { d.querySelector('#fld-list').innerHTML = draw(); persist(); }; d.addEventListener('click', (e) => { const del = e.target.closest('[data-fld-del]'); if (del) { m.fields.splice(+del.dataset.fldDel, 1); redraw(); } if (e.target.closest('#fld-add')) { const n = d.querySelector('#fld-name').value.trim(); if (!n) return; m.fields = m.fields || []; m.fields.push({ name: n, type: d.querySelector('#fld-type').value }); d.querySelector('#fld-name').value = ''; redraw(); DM.toast('Field added'); } }); } }); });

  /* ───────── Humans ───────── */
  const HU = () => (DM.ui.stHu = DM.ui.stHu || { tab: 'members', q: '' });
  const ROLENAMES = () => ['Admin', 'Owner', 'ASM', 'Sales', 'Accounts', ...(DM.S.roles || []).map((r) => r.name)].filter((x, i, a) => a.indexOf(x) === i);
  reg('users', 'Humans', () => {
    const u = HU(); const users = DM.S.users || []; const roles = DM.S.roles || []; const inv = DM.S.invites || []; const q = u.q.toLowerCase();
    const tab = (k, l, n) => `<button class="${u.tab === k ? 'on' : ''}" data-act="st-hutab" data-arg="${k}">${l} <span class="cnt-chip">${n}</span></button>`;
    let body = '';
    if (u.tab === 'members') {
      const rows = users.filter((x) => !q || (x.name + ' ' + (x.email || '') + ' ' + x.role).toLowerCase().includes(q));
      body = DM.table([
        { label: 'Name', flex: 1.3, render: (x) => `<span class="row gap4"><span class="av-dark">${esc(DM.initials(x.name))}</span><b style="font-weight:500">${esc(x.name)}</b></span>` },
        { label: 'Email', flex: 1.3, render: (x) => `<span class="muted">${esc(x.email || '—')}</span>` },
        { label: 'Role', w: '110px', k: 'role', render: (x) => esc(x.role) },
        { label: 'Status', w: '110px', render: (x) => `<span class="member-chip">${x.status === 'invited' ? 'Invited' : 'Member'}</span>` },
        { label: 'Joined', w: '130px', render: (x) => `<span class="muted">${esc(fmt.date(x.joined || '2026-10-14'))}</span>` },
        { label: '', w: '120px', render: (x) => `<span class="row gap4" style="justify-content:flex-end">${x.phone ? `<button class="btn ghost icon sm" data-act="st-hucall" data-arg="${esc(x.id)}" title="${esc(x.phone)}">${I('phone')}</button>` : ''}${x.email ? `<button class="btn ghost icon sm" data-act="st-humail" data-arg="${esc(x.id)}" title="${esc(x.email)}">${I('mail')}</button>` : ''}<button class="btn ghost icon sm" data-act="st-user-menu" data-arg="${esc(x.id)}">${I('more')}</button></span>` },
      ], rows, { empty: 'No one matches that search.' });
    } else if (u.tab === 'roles') {
      body = `<div class="row" style="margin:14px 0 10px"><div class="sm muted grow">Custom roles bundle module access. Admin, Owner, ASM, Sales and Accounts are built in.</div>${DM.btn('New role', 'st-role-new', { icon: 'plus', cls: 'outline sm' })}</div>` + DM.table([{ label: 'Role', render: (r) => `<b style="font-weight:500">${esc(r.name)}</b>` }, { label: 'Access', flex: 2, render: (r) => `<span class="muted">${esc(r.access)}</span>` }, { label: 'Members', w: '100px', num: true, render: (r) => r.members }, { label: '', w: '90px', render: (r) => `<span class="row gap4" style="justify-content:flex-end">${pencil('st-role-edit', r.id)}<button class="btn ghost icon sm" data-act="st-role-del" data-arg="${esc(r.id)}">${I('trash')}</button></span>` }], roles, { empty: 'No custom roles yet.' });
    } else {
      body = `<div class="row" style="margin:14px 0 10px"><div class="sm muted grow">People who were invited but have not accepted yet.</div>${DM.btn('Invite', 'st-invite', { icon: 'plus', cls: 'outline sm' })}</div>` + DM.table([{ label: 'Email', flex: 1.6, render: (r) => esc(r.email) }, { label: 'Role', w: '120px', render: (r) => esc(r.role) }, { label: 'Sent', w: '120px', render: (r) => `<span class="muted">${esc(fmt.date(r.sent))}</span>` }, { label: '', w: '190px', render: (r) => `<span class="row gap4" style="justify-content:flex-end"><button class="btn outline sm" data-act="st-inv-resend" data-arg="${esc(r.id)}">Resend</button><button class="btn ghost sm" data-act="st-inv-revoke" data-arg="${esc(r.id)}">Revoke</button></span>` }], inv, { empty: 'No pending invites.' });
    }
    return page('Humans', 'Manage who has access to this workspace and what they can do.', `<div class="row" style="align-items:flex-end"><div class="hu-tabs grow" style="border:0;margin:0">${tab('members', 'Members', users.length)}${tab('roles', 'Roles', roles.length)}${tab('invites', 'Invites', inv.length)}</div>${DM.searchBox('st-huq', 'Search people…', u.q)}</div><div style="border-top:1px solid var(--border);margin-bottom:${u.tab === 'members' ? 12 : 0}px"></div>${body}`, `<button class="btn outline" data-act="st-newmember">New member</button><button class="btn" data-act="st-invite">${I('user')} Invite</button>`);
  });
  DM.act('st-hutab', (el) => { HU().tab = el.dataset.arg; DM.render(); });
  DM.input('st-huq', (v) => { HU().q = v; DM.render(); });
  DM.act('st-hucall', (el) => { const x = DM.by(DM.S.users, el.dataset.arg); DM.toast('Calling ' + x.name + ' · ' + x.phone, 'phone'); });
  DM.act('st-humail', (el) => { const x = DM.by(DM.S.users, el.dataset.arg); DM.toast('Opening mail to ' + x.email, 'mail'); });
  const MODS = ['Inbox', 'Orders', 'CRM', 'Products', 'Agents', 'Workflows'];
  DM.act('st-invite', () => DM.modal({ title: 'Invite a human', body: `<div class="col gap12">${DM.field('Email', 'email', { type: 'email', ph: 'name@company.com' })}${DM.field('Role', 'role', { options: ROLENAMES().filter((r) => r !== 'Owner'), value: 'Sales' })}${DM.field('Message (optional)', 'msg', { area: true, rows: 2, ph: 'Welcome to the workspace.' })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Send invite', run: (m) => { const f = DM.formData(m); if (!/^\S+@\S+\.\S+$/.test(f.email)) { DM.toast('Enter a valid email', 'alert'); return false; } (DM.S.invites = DM.S.invites || []).unshift({ id: DM.uid('inv'), email: f.email, role: f.role, sent: new Date().toISOString().slice(0, 10) }); HU().tab = 'invites'; done('Invite sent to ' + f.email, 'mail'); } }] }));
  DM.act('st-newmember', () => DM.modal({ title: 'New member', body: `<div class="col gap12">${DM.field('Full name', 'name', { ph: 'Full name' })}${DM.field('Email', 'email', { type: 'email' })}${DM.field('Phone', 'phone', { ph: '+91 …' })}${DM.field('Role', 'role', { options: ROLENAMES().filter((r) => r !== 'Owner'), value: 'Sales' })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Add member', run: (m) => { const f = DM.formData(m); if (!f.name.trim() || !/@/.test(f.email)) { DM.toast('Name and a valid email are required', 'alert'); return false; } DM.S.users.unshift({ id: DM.uid('u'), name: f.name.trim(), email: f.email, phone: f.phone, role: f.role, status: 'active', last: '—', joined: new Date().toISOString().slice(0, 10), modules: MODS }); HU().tab = 'members'; done(f.name.trim() + ' added'); } }] }));
  DM.act('st-user-menu', (el) => { const x = DM.by(DM.S.users, el.dataset.arg); DM.menu(el, [{ label: 'Edit details', icon: 'edit', run: () => DM.modal({ title: 'Edit ' + x.name, body: `<div class="col gap12">${DM.field('Name', 'name', { value: x.name })}${DM.field('Email', 'email', { value: x.email || '' })}${DM.field('Phone', 'phone', { value: x.phone || '' })}${x.role === 'Owner' ? '' : DM.field('Role', 'role', { options: ROLENAMES().filter((r) => r !== 'Owner'), value: x.role })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (m) => { Object.assign(x, DM.formData(m)); done('Saved'); } }] }) }, ...(x.status === 'invited' ? [{ label: 'Resend invite', icon: 'mail', run: () => DM.toast('Invite resent', 'mail') }] : []), { label: 'Copy email', icon: 'copy', run: () => { try { navigator.clipboard.writeText(x.email || ''); } catch (e) {} DM.toast('Email copied'); } }, ...(x.role !== 'Owner' ? [{ label: 'Remove', icon: 'trash', run: () => DM.confirm('Remove ' + x.name + '?', 'They will lose access immediately. Cases they own go back to Anuma.', () => { DM.S.users = DM.S.users.filter((y) => y.id !== x.id); done('Removed'); }, 'Remove') }] : [])]); });
  DM.act('st-inv-resend', (el) => { const r = DM.by(DM.S.invites, el.dataset.arg); DM.toast('Invite resent to ' + r.email, 'mail'); });
  DM.act('st-inv-revoke', (el) => { const r = DM.by(DM.S.invites, el.dataset.arg); DM.confirm('Revoke invite?', esc(r.email) + ' will no longer be able to join.', () => { DM.S.invites = DM.S.invites.filter((y) => y.id !== r.id); done('Invite revoked'); }, 'Revoke'); });
  const roleForm = (r) => DM.modal({ title: r ? 'Edit role' : 'New role', body: `<div class="col gap12">${DM.field('Role name', 'name', { value: r?.name || '', ph: 'Order reviewer' })}<div class="field"><label>Module access</label><div class="row wrap" style="gap:10px">${MODS.map((m) => `<label class="row sm"><input type="checkbox" name="m_${m}" ${!r || r.access.includes(m) ? 'checked' : ''}> ${m}</label>`).join('')}</div></div></div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save role', run: (m) => { const f = DM.formData(m); if (!f.name.trim()) { DM.toast('Give the role a name', 'alert'); return false; } const access = MODS.filter((x) => f['m_' + x]).join(', ') || 'No modules'; if (r) { r.name = f.name.trim(); r.access = access; } else (DM.S.roles = DM.S.roles || []).push({ id: DM.uid('role'), name: f.name.trim(), access, members: 0 }); done('Role saved'); } }] });
  DM.act('st-role-new', () => roleForm(null)); DM.act('st-role-edit', (el) => roleForm(DM.by(DM.S.roles, el.dataset.arg)));
  DM.act('st-role-del', (el) => { const r = DM.by(DM.S.roles, el.dataset.arg); DM.confirm('Delete role “' + esc(r.name) + '”?', 'People with this role keep their access until you reassign them.', () => { DM.S.roles = DM.S.roles.filter((y) => y.id !== r.id); done('Role deleted'); }, 'Delete'); });

  /* ───────── Rulebook ───────── */
  const RK = { rule: ['Rules', 'check'], guardrail: ['Guardrails', 'shield'], helper: ['Helpers', 'wand'] };
  const V = () => DM.S.voice || (DM.S.voice = { writes: [], never: [], channels: [] });
  reg('rulebook', 'Rulebook', () => {
    const v = V(); const rb = DM.S.rulebook || (DM.S.rulebook = []); const ui = (DM.ui.stRb = DM.ui.stRb || { adding: false });
    return page('Rulebook', 'How Anuma sounds and behaves, and what it may do without you.',
      `<div class="st-eyebrow" style="margin-top:4px">Voice</div>
      <div class="card st-card"><div class="hd"><div class="grow"><h3>How it writes</h3></div><button class="btn outline sm" data-act="st-vw-edit">Edit</button>${pencil('st-vw-edit')}</div><div class="body vtext">${v.writes.map((t) => `<p>${esc(t)}</p>`).join('') || '<div class="muted sm">Nothing written yet.</div>'}</div></div>
      <div class="card st-card"><div class="hd"><div class="grow"><h3>Never say <span class="cnt-chip" style="margin-left:4px">${v.never.length}</span></h3><div class="s">Words and fragments that never go out to a customer.</div></div><span class="icotile">${I('x')}</span></div><div class="body"><div class="chips">${v.never.map((p, i) => `<span class="chip">${esc(p)}<button data-act="st-nv-del" data-arg="${i}" title="Remove">${I('x')}</button></span>`).join('')}${ui.adding ? `<input class="input" id="nv-new" style="width:200px;height:26px" placeholder="Type a phrase, press Enter" data-input="st-nv-draft">` : `<button class="addphrase" data-act="st-nv-add">${I('plus')} Add phrase</button>`}</div></div></div>
      <div class="card st-card"><div class="hd"><div class="grow"><h3>Per-channel rules</h3><div class="s">Extra rules that apply on one channel only.</div></div><button class="btn outline sm" data-act="st-ch-edit" data-arg="">Edit</button><span class="icotile">${I('chat')}</span></div><div class="body">${v.channels.map((c) => `<div class="vlab" style="margin-top:0">${esc(c.label)} <button class="btn ghost icon sm" data-act="st-ch-edit" data-arg="${esc(c.id)}" style="vertical-align:middle">${I('edit')}</button></div><p class="sm" style="line-height:1.5;margin-bottom:14px">${esc(c.text)}</p>`).join('')}</div></div>
      ${['rule', 'guardrail', 'helper'].map((k) => { const [l, ic] = RK[k]; const rs = rb.filter((r) => r.kind === k); return `<div class="st-eyebrow">${l === 'Rules' ? 'What it may do' : l}</div><div class="card st-card"><div class="hd"><span style="color:var(--muted-foreground)">${I(ic)}</span><div class="grow"><h3>${l} <span class="cnt-chip" style="margin-left:4px">${rs.length}</span></h3><div class="s">${k === 'rule' ? 'Business rules every agent follows.' : k === 'guardrail' ? 'Hard limits. The agent hands off instead of crossing them.' : 'Small helpers that make replies faster.'}</div></div><button class="btn outline sm" data-act="rb-edit" data-arg="|${k}">${I('plus')} Add</button></div><div style="margin-top:10px">${rs.length ? rs.map((r) => `<div class="st-row" style="align-items:flex-start"><div class="grow sm ${r.enabled === false ? 'muted' : ''}" style="${r.enabled === false ? 'text-decoration:line-through' : ''}">${esc(r.text)}<div class="xs muted" style="margin-top:2px">${r.scope === 'agent' ? 'Agent-specific' : 'Inherited by all agents'}</div></div>${DM.switch(r.enabled !== false, 'rb-toggle', r.id)}${pencil('rb-edit', r.id + '|' + k)}<button class="btn ghost icon sm" data-act="rb-del" data-arg="${esc(r.id)}">${I('trash')}</button></div>`).join('') : '<div class="empty sm" style="padding:18px">Nothing here yet.</div>'}</div></div>`; }).join('')}`);
  });
  DM.act('st-vw-edit', () => DM.modal({ lg: true, title: 'How it writes', body: `<div class="sm muted" style="margin-bottom:8px">One rule per line. These shape every reply, on every channel.</div>${DM.field('Rules', 'text', { value: V().writes.join('\n'), area: true, rows: 12 })}`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (m) => { V().writes = DM.formData(m).text.split('\n').map((s) => s.trim()).filter(Boolean); done('Voice updated'); } }] }));
  DM.act('st-nv-del', (el) => { V().never.splice(+el.dataset.arg, 1); done(); });
  DM.act('st-nv-add', () => { DM.ui.stRb.adding = true; DM.render(); const i = document.getElementById('nv-new'); if (i) { i.focus(); i.onkeydown = (e) => { if (e.key === 'Enter' && i.value.trim()) { V().never.push(i.value.trim()); DM.ui.stRb.adding = false; done('Phrase added'); } else if (e.key === 'Escape') { DM.ui.stRb.adding = false; DM.render(); } }; i.onblur = () => { if (DM.ui.stRb.adding && !i.value.trim()) { DM.ui.stRb.adding = false; DM.render(); } }; } });
  DM.input('st-nv-draft', () => {});
  DM.act('st-ch-edit', (el) => { const v = V(); const id = el.dataset.arg; const list = id ? v.channels.filter((c) => c.id === id) : v.channels; DM.modal({ lg: true, title: id ? 'Edit ' + list[0].label + ' rules' : 'Edit per-channel rules', body: `<div class="col gap12">${list.map((c) => DM.field(c.label, 'c_' + c.id, { value: c.text, area: true, rows: 7 })).join('')}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (m) => { const f = DM.formData(m); list.forEach((c) => { c.text = (f['c_' + c.id] || '').trim(); }); done('Channel rules saved'); } }] }); });
  DM.act('rb-toggle', (el) => { const r = DM.by(DM.S.rulebook, el.dataset.arg); r.enabled = r.enabled === false; done(); });
  DM.act('rb-del', (el) => DM.confirm('Delete rule?', 'Agents will stop following it.', () => { DM.S.rulebook = DM.S.rulebook.filter((r) => r.id !== el.dataset.arg); done('Deleted'); }, 'Delete'));
  DM.act('rb-edit', (el) => { const [id, kind] = el.dataset.arg.split('|'); const r = id ? DM.by(DM.S.rulebook, id) : null; DM.modal({ title: r ? 'Edit rule' : 'Add ' + kind, body: `<div class="col gap12">${DM.field('Rule', 'text', { value: r?.text || '', area: true, rows: 4, ph: 'Always confirm the shade before recording a line.' })}<div class="field"><label>Applies to</label><select class="select" name="scope"><option value="inherited" ${r?.scope !== 'agent' ? 'selected' : ''}>All agents</option><option value="agent" ${r?.scope === 'agent' ? 'selected' : ''}>Agent-specific</option></select></div></div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Save', run: (m) => { const f = DM.formData(m); if (!f.text.trim()) { DM.toast('Write the rule first', 'alert'); return false; } if (r) { r.text = f.text.trim(); r.scope = f.scope; } else DM.S.rulebook.push({ id: DM.uid('rb'), kind, scope: f.scope, text: f.text.trim(), enabled: true }); done('Saved'); } }] }); });

  /* ───────── Usage ───────── */
  const cmp = (n) => (n >= 1e6 ? (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M' : n >= 1e3 ? (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K' : String(Math.round(n * 10) / 10));
  const pctLabel = (p) => (p > 0 && p < 1 ? '<1%' : Math.round(p) + '%');
  const dmy = (d) => new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
  const dshort = (d) => new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
  reg('usage', 'Usage', () => {
    const u = DM.S.usageCycle; if (!u) return page('Usage', '', '<div class="empty">No usage yet.</div>');
    const D = 86400000; const t0 = new Date(u.start), t1 = new Date(u.end), tn = new Date(u.today); const total = Math.round((t1 - t0) / D), day = Math.round((tn - t0) / D) + 1, left = total - day; const frac = day / total;
    const calc = (i) => { const p = (i.used / i.limit) * 100; const proj = i.used / frac; return { p, proj, pp: Math.min(100, (proj / i.limit) * 100) }; };
    const ring = (p) => { const r = 18, c = 2 * Math.PI * r; return `<svg width="46" height="46" viewBox="0 0 46 46"><circle cx="23" cy="23" r="${r}" fill="none" stroke="#eee" stroke-width="5"/><circle cx="23" cy="23" r="${r}" fill="none" stroke="#13a269" stroke-width="5" stroke-linecap="round" stroke-dasharray="${(Math.max(p, p > 0 ? 2 : 0) / 100) * c} ${c}" transform="rotate(-90 23 23)"/><text x="23" y="26.5" text-anchor="middle" font-size="10" font-weight="600" fill="#171717">${p > 0 && p < 1 ? '<1%' : Math.round(p) + '%'}</text></svg>`; };
    const dcards = u.donuts.map((d) => { const c = calc(d); return `<div class="card dcard">${ring(c.p)}<div style="min-width:0"><div class="xs muted">${esc(d.label)}${d.tag ? ' · ' + esc(d.tag) : ''}</div><div style="font-size:16px;font-weight:600;margin:1px 0">${cmp(d.used)} <span class="muted" style="font-weight:400;font-size:12px">/ ${cmp(d.limit)}</span></div><div class="xs muted">On pace for ${pctLabel(c.pp)} by ${dshort(u.end)}</div></div></div>`; }).join('');
    const secs = u.sections.map((s) => `<div class="card st-card"><div class="hd"><div class="grow"><h3>${esc(s.title)}</h3></div><span class="icotile">${I(s.icon)}</span></div><div style="margin-top:8px">${s.items.map((i) => { const c = calc(i); return `<div class="urow"><div class="row"><span class="sm b" style="font-weight:500">${esc(i.label)}</span>${i.hard ? '<span class="badge amber" style="margin-left:6px">hard cap</span>' : ''}<span class="right sm"><b style="font-weight:600">${cmp(i.used)}</b> <span class="muted">/ ${cmp(i.limit)} ${esc(i.unit)}</span> <span class="up" style="margin-left:10px;font-weight:500">${pctLabel(c.p)}</span></span></div><div class="ubar"><i class="u" style="width:${Math.min(100, c.p)}%"></i><i class="p" style="left:${Math.min(100, c.p)}%;width:${Math.max(0, c.pp - Math.min(100, c.p))}%"></i><b class="t" style="left:${frac * 100}%"></b></div><div class="row xs muted"><span>${i.note ? esc(i.note) : `Projected by ${dshort(u.end)}: ${cmp(c.proj)} (${pctLabel(c.pp)})`}</span><span class="right">${esc(i.overage || '')}</span></div></div>`; }).join('')}</div></div>`).join('');
    return page('Usage', 'Where this cycle stands against your plan.',
      `<div class="card st-card cyc"><div class="row"><span class="big"><b>Day ${day} of ${total}</b> <span class="muted">of this cycle</span></span><span class="right sm muted">${left} days left</span></div><div class="track"><i style="width:${frac * 100}%"></i></div><div class="row xs muted"><span>${dmy(u.start)}</span><span class="right">${dmy(u.end)}</span></div></div>
      <div class="donuts">${dcards}</div><div class="legend"><span><i style="width:14px;height:6px;border-radius:3px;background:#13a269"></i>Used</span><span><i style="width:2px;height:12px;background:#404040"></i>Where the cycle is today</span><span><i style="width:14px;height:6px;background:repeating-linear-gradient(90deg,#13a269 0 2px,transparent 2px 5px);opacity:.6"></i>Projected at this pace</span></div>${secs}`,
      `<span class="badge outline">${esc(u.plan)}</span>${DM.btn('Upgrade plan', 'us-up', { cls: 'sm' })}`);
  });
  DM.act('us-up', () => DM.modal({ title: 'Choose a plan', body: `<div class="grid g3">${[['Starter', 4999, '10 humans · 1 number'], ['Growth', 14999, '25 humans · 3 numbers'], ['Scale', 39999, 'Unlimited humans · 10 numbers']].map(([n, p, d]) => `<label class="card pad" style="display:flex;flex-direction:column;gap:4px;cursor:pointer"><input type="radio" name="plan" value="${n}" ${(DM.S.usageCycle.plan || '').startsWith(n) ? 'checked' : ''}><div class="b">${n}</div><div class="b" style="font-size:18px">${fmt.inr(p)}<span class="xs muted">/mo</span></div><div class="xs muted">${d}</div></label>`).join('')}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Switch plan', run: (m) => { const sel = m.querySelector('input[name=plan]:checked'); if (sel) { DM.S.usageCycle.plan = sel.value + ' plan'; DM.S.plan.name = sel.value + ' plan'; DM.S.plan.title = sel.value; DM.toast('Plan changed to ' + sel.value); DM.render(); } } }] }));

  /* ───────── Templates ───────── */
  reg('templates', 'Templates', () => {
    const t = DM.S.templates || (DM.S.templates = []); const u = (DM.ui.tp = DM.ui.tp || { f: 'all' });
    const rows = t.filter((x) => u.f === 'all' || x.status === u.f);
    return page('Templates', 'Message templates for WhatsApp, email and quotes.', `<div class="row" style="margin-bottom:12px">${DM.pills([{ key: 'all', label: 'All' }, { key: 'approved', label: 'Approved' }, { key: 'pending', label: 'Pending' }, { key: 'rejected', label: 'Rejected' }], u.f, 'tp-f')}</div>` + DM.table([{ label: 'Name', flex: 2, render: (x) => `<b style="font-weight:500">${esc(x.name)}</b> <span class="muted">· ${esc((x.body || '').slice(0, 60))}</span>` }, { label: 'Channel', w: '100px', render: (x) => esc(x.channel || 'whatsapp') }, { label: 'Category', w: '110px', render: (x) => esc(x.category || 'Utility') }, { label: 'Language', w: '90px', render: (x) => esc(x.lang || 'en') }, { label: 'Status', w: '120px', render: (x) => DM.status(x.status, x.status === 'approved' ? 'green' : x.status === 'pending' ? 'amber' : 'red') }, { label: '', w: '60px', render: (x) => `<button class="btn ghost icon sm" data-act="tp-menu" data-arg="${esc(x.id)}">${I('more')}</button>` }], rows, { empty: 'No templates in this view.', click: 'tp-prev' }), DM.btn('New template', 'tp-edit', { icon: 'plus', arg: '' }), ['/settings/organisation', 'Company']);
  });
  DM.act('tp-f', (el) => { DM.ui.tp.f = el.dataset.arg; DM.render(); });
  DM.act('tp-prev', (el) => { const x = DM.by(DM.S.templates, el.dataset.arg); if (x) tpPrev(x); });
  DM.act('tp-menu', (el) => { const x = DM.by(DM.S.templates, el.dataset.arg); DM.menu(el, [{ label: 'Preview', icon: 'eye', run: () => tpPrev(x) }, { label: 'Edit', icon: 'edit', run: () => tpEdit(x.id) }, { label: 'Duplicate', icon: 'copy', run: () => { DM.S.templates.push(Object.assign(DM.clone(x), { id: DM.uid('tp'), name: x.name + '_copy', status: 'pending' })); done('Duplicated'); } }, { label: 'Delete', icon: 'trash', run: () => DM.confirm('Delete template?', esc(x.name), () => { DM.S.templates = DM.S.templates.filter((y) => y.id !== x.id); done(); }, 'Delete') }]); });
  function tpPrev(x) { DM.drawer({ title: esc(x.name), body: `<div class="chatbg" style="padding:24px;border-radius:12px"><div class="bub" style="max-width:100%">${esc((x.body || '').replace(/\{\{\d+\}\}/g, '…'))}<span class="tm">10:42</span></div></div><dl class="kv" style="margin-top:16px"><dt>Channel</dt><dd>${esc(x.channel || 'whatsapp')}</dd><dt>Category</dt><dd>${esc(x.category || 'Utility')}</dd><dt>Status</dt><dd>${esc(x.status)}</dd></dl>` }); }
  function tpEdit(id) {
    const x = id ? DM.by(DM.S.templates, id) : null;
    DM.modal({ title: x ? 'Edit template' : 'New template', body: `<div class="col gap12">${DM.field('Name', 'name', { value: x?.name || '', ph: 'order_confirmation' })}<div class="grid g2">${DM.field('Channel', 'channel', { options: ['whatsapp', 'email', 'sms'], value: x?.channel || 'whatsapp' })}${DM.field('Category', 'category', { options: ['Utility', 'Marketing', 'Authentication'], value: x?.category || 'Utility' })}</div>${DM.field('Body', 'body', { value: x?.body || '', area: true, rows: 5, ph: 'Hi {{1}}, your order {{2}} is confirmed.' })}<div class="xs muted">Use {{1}}, {{2}} for variables. WhatsApp templates are reviewed before use.</div></div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: x ? 'Save' : 'Submit for approval', run: (m) => { const f = DM.formData(m); if (!f.name.trim() || !f.body.trim()) { DM.toast('Name and body required', 'alert'); return false; } let t = x; if (x) Object.assign(x, f); else { t = Object.assign({ id: DM.uid('tp'), status: 'pending', lang: 'en' }, f); DM.S.templates.unshift(t); setTimeout(() => { t.status = 'approved'; DM.toast(`“${t.name}” approved`, 'check'); if (DM.path().startsWith('/settings/templates')) DM.render(); }, 3000); } done(x ? 'Template saved' : 'Submitted for approval'); } }] });
  }
  DM.act('tp-edit', (el) => tpEdit(el.dataset.arg || null));

  /* ───────── Tax ───────── */
  reg('taxes', 'Tax', () => {
    const t = S().taxes;
    return page('Tax', 'GST rates applied to products, quotes and invoices.', card('Defaults', null, `<div class="grid g2">${inp('Default GST rate (%)', 'settings.taxes.defaultRate', { type: 'number' })}${inp('GSTIN', 'company.gstin', { hint: 'Shared with Company settings' })}</div><div class="col" style="margin-top:14px;gap:10px"><label class="row sm">${DM.switch(t.inclusive, 'st-flip', 'settings.taxes.inclusive')} Prices include tax</label><label class="row sm">${DM.switch(t.hsnRequired, 'st-flip', 'settings.taxes.hsnRequired')} Require HSN code on products</label></div>`)
      + `<div class="card st-card"><div class="hd"><h3 class="grow">Tax rates</h3><button class="btn outline sm" data-act="tx-add">${I('plus')} Add rate</button></div><div style="margin-top:8px">${t.rates.map((r) => `<div class="st-row"><div class="grow"><div class="sm b">${esc(r.name)}</div></div><span class="mono sm">${r.rate}%</span>${DM.switch(r.on, 'tx-tog', r.id)}<button class="btn ghost icon sm" data-act="tx-del" data-arg="${esc(r.id)}">${I('trash')}</button></div>`).join('')}</div></div>`, '', ['/settings/organisation', 'Company']);
  });
  DM.act('tx-tog', (el) => { const r = DM.by(S().taxes.rates, el.dataset.arg); r.on = !r.on; done(); });
  DM.act('tx-del', (el) => { S().taxes.rates = S().taxes.rates.filter((r) => r.id !== el.dataset.arg); done('Rate removed'); });
  DM.act('tx-add', () => DM.modal({ title: 'Add tax rate', body: `<div class="col gap12">${DM.field('Name', 'name', { ph: 'GST 3%' })}${DM.field('Rate (%)', 'rate', { type: 'number', value: 3 })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Add', run: (m) => { const f = DM.formData(m); if (!f.name.trim()) { DM.toast('Name the rate', 'alert'); return false; } S().taxes.rates.push({ id: DM.uid('g'), name: f.name, rate: +f.rate, on: true }); done('Rate added'); } }] }));

  /* ───────── Shipping ───────── */
  reg('shipping', 'Shipping', () => {
    const s = S().shipping;
    return page('Shipping', 'Carriers, zones and free-shipping rules.', card('Rules', null, `<div class="grid g3">${inp('Free shipping above (₹)', 'settings.shipping.freeAbove', { type: 'number' })}${inp('Flat rate otherwise (₹)', 'settings.shipping.flat', { type: 'number' })}${inp('Pickup location', 'settings.shipping.pickup')}</div>`)
      + `<div class="card st-card"><div class="hd"><h3 class="grow">Carriers</h3></div><div style="margin-top:8px">${s.carriers.map((c) => `<div class="st-row"><span style="color:var(--muted-foreground)">${I('truck')}</span><div class="grow"><div class="sm b">${esc(c.name)}</div><div class="xs muted">${esc(c.mode)}</div></div>${DM.switch(c.on, 'sh-tog', c.id)}</div>`).join('')}</div></div>`
      + `<div class="hd" style="padding:0;margin:18px 0 8px"><h3 class="grow" style="font-size:14px">Zones</h3><button class="btn outline sm" data-act="sh-add">${I('plus')} Add zone</button></div>` + DM.table([{ label: 'Zone', flex: 2, render: (z) => esc(z.name) }, { label: 'Transit', render: (z) => z.days + ' days' }, { label: 'Rate', num: true, render: (z) => fmt.inr(z.rate) }, { label: '', w: '60px', render: (z) => `<button class="btn ghost icon sm" data-act="sh-del" data-arg="${esc(z.id)}">${I('trash')}</button>` }], s.zones, { empty: 'No zones yet.' }), '', ['/settings/organisation', 'Company']);
  });
  DM.act('sh-tog', (el) => { const c = DM.by(S().shipping.carriers, el.dataset.arg); c.on = !c.on; done(c.name + (c.on ? ' enabled' : ' disabled')); });
  DM.act('sh-del', (el) => { S().shipping.zones = S().shipping.zones.filter((z) => z.id !== el.dataset.arg); done(); });
  DM.act('sh-add', () => DM.modal({ title: 'Add zone', body: `<div class="col gap12">${DM.field('Zone name', 'name', { ph: 'North-East' })}${DM.field('Transit days', 'days', { ph: '5–8' })}${DM.field('Rate (₹)', 'rate', { type: 'number', value: 350 })}</div>`, actions: [{ label: 'Cancel', cls: 'outline' }, { label: 'Add', run: (m) => { const f = DM.formData(m); if (!f.name.trim()) { DM.toast('Name the zone', 'alert'); return false; } S().shipping.zones.push({ id: DM.uid('z'), name: f.name, days: f.days || '—', rate: +f.rate }); done('Zone added'); } }] }));

  /* ───────── Invoices ───────── */
  reg('invoices', 'Invoices', () => {
    const v = S().invoices;
    return page('Invoices', 'Numbering, terms and layout of tax invoices.', card('Numbering', null, `<div class="grid g2">${inp('Prefix', 'settings.invoices.prefix')}${inp('Next number', 'settings.invoices.next', { type: 'number' })}</div><div class="xs muted" style="margin-top:8px">Next invoice: <b>${esc(v.prefix)}${v.next}</b></div>`)
      + card('Content', null, `<div class="col gap12">${inp('Terms & conditions', 'settings.invoices.terms', { area: true, rows: 3 })}${inp('Bank details', 'settings.invoices.bank')}<label class="row sm">${DM.switch(v.showHsn, 'st-flip', 'settings.invoices.showHsn')} Show HSN column</label><label class="row sm">${DM.switch(v.signature, 'st-flip', 'settings.invoices.signature')} Authorised signature block</label><label class="row sm">${DM.switch(v.qr, 'st-flip', 'settings.invoices.qr')} UPI payment QR</label></div>`, `<button class="btn outline sm" data-act="inv-prev">${I('eye')} Preview</button>${DM.btn('Save changes', 'st-save', { cls: 'sm', arg: 'Invoice settings saved' })}`), '', ['/settings/organisation', 'Company']);
  });
  DM.act('inv-prev', () => { const v = S().invoices, c = DM.S.company || {}; const lines = (DM.S.products || []).slice(0, 3); DM.modal({ lg: true, title: 'Invoice preview', body: `<div class="inv-prev"><div class="row"><div><div class="b" style="font-size:16px">${esc(c.legal || c.name || 'Demo Merchant User')}</div><div class="muted">GSTIN ${esc(c.gstin || '—')}<br>${esc(c.address || '')}, ${esc(c.city || '')}</div></div><div class="right" style="text-align:right"><div class="b">TAX INVOICE</div><div class="mono">${esc(v.prefix)}${v.next}</div></div></div><table class="tbl" style="margin:16px 0"><thead><tr><th>Item</th>${v.showHsn ? '<th>HSN</th>' : ''}<th class="num">Qty</th><th class="num">Rate</th><th class="num">Amount</th></tr></thead><tbody>${lines.map((p, i) => `<tr><td>${esc(p.name)}</td>${v.showHsn ? `<td>${esc(p.hsn || '—')}</td>` : ''}<td class="num">${(i + 1) * 10}</td><td class="num">${fmt.inr(p.price)}</td><td class="num">${fmt.inr(p.price * (i + 1) * 10)}</td></tr>`).join('')}</tbody></table><div class="muted">${esc(v.bank)}</div><div class="muted" style="margin-top:8px">${esc(v.terms)}</div>${v.signature ? '<div style="text-align:right;margin-top:20px" class="muted">Authorised signatory</div>' : ''}</div>` }); });

  DM.searchProviders.push((q) => [['organisation', 'Company'], ['navigation', 'Navigation'], ['users', 'Humans'], ['rulebook', 'Rulebook'], ['usage', 'Usage'], ['templates', 'Templates'], ['taxes', 'Tax'], ['shipping', 'Shipping'], ['invoices', 'Invoices'], ['personal', 'Personal']].filter(([, l]) => l.toLowerCase().includes(q)).map(([k, l]) => ({ label: l, sub: 'Settings', icon: 'settings', url: '/settings/' + k })));
})();
